using(var t=new Transaction(document,"A07 garage access door setout correction")){t.Start();var e=new FilteredElementCollector(document).OfClass(typeof(FamilyInstance)).Cast<FamilyInstance>().Single(e=>e.get_Parameter(BuiltInParameter.ALL_MODEL_MARK)?.AsString()=="D-GAR-ACCESS");var pt=(LocationPoint)e.Location;pt.Point=new XYZ(pt.Point.X,4160/304.8,pt.Point.Z);var ids=new FilteredElementCollector(document).OfClass(typeof(FamilyInstance)).Cast<FamilyInstance>().Where(e=>(e.get_Parameter(BuiltInParameter.ALL_MODEL_MARK)?.AsString()??"").StartsWith("WF-GF-GAR-P-")).Select(e=>e.Id).ToList();foreach(var id in ids)document.Delete(id);t.Commit();}document.Save();return document.GetWarnings().Select(w=>w.GetDescriptionText()).ToArray();
